mapper.select:
SELECT count(*)
FROM batch.process_staging
WHERE tenant_id = #{candidate.tenantId}
  AND staging_generation_id = CAST(#{candidate.generationId} AS uuid)
  AND batch_key = #{candidate.batchKey}
  AND staged_at < now() - make_interval(hours => #{retentionHours})

SELECT min(staged_at)
FROM batch.process_staging
WHERE tenant_id = #{candidate.tenantId}
  AND staging_generation_id = CAST(#{candidate.generationId} AS uuid)
  AND batch_key = #{candidate.batchKey}

SELECT generation_status
FROM batch.process_staging_generation
WHERE tenant_id = #{tenantId}
  AND job_task_id = #{taskId}
  AND generation_id = CAST(#{generationId} AS uuid)
  AND batch_key = #{batchKey}
FOR UPDATE

mapper.update:
UPDATE batch.process_staging_generation
SET generation_status = #{targetStatus}, sealed_at = now()
WHERE tenant_id = #{candidate.tenantId}
  AND job_task_id = #{candidate.taskId}
  AND generation_id = CAST(#{candidate.generationId} AS uuid)
  AND batch_key = #{candidate.batchKey}
  AND generation_status = 'OPEN'

UPDATE batch.process_staging_generation generation
SET generation_status = #{targetStatus}
WHERE generation.tenant_id = #{candidate.tenantId}
  AND generation.job_task_id = #{candidate.taskId}
  AND generation.generation_id = CAST(#{candidate.generationId} AS uuid)
  AND generation.batch_key = #{candidate.batchKey}
  AND generation.generation_status = 'SEALED'
  AND NOT EXISTS (
    SELECT 1
    FROM batch.process_staging staging
    WHERE staging.tenant_id = generation.tenant_id
      AND staging.staging_generation_id = generation.generation_id
      AND staging.batch_key = generation.batch_key
  )

mapper.delete:
DELETE FROM batch.process_staging AS target
USING (
  SELECT tableoid, ctid
  FROM batch.process_staging
  WHERE tenant_id = #{candidate.tenantId}
    AND staging_generation_id = CAST(#{candidate.generationId} AS uuid)
    AND batch_key = #{candidate.batchKey}
  ORDER BY staged_at
  LIMIT #{batchSize}
  FOR UPDATE SKIP LOCKED
) AS victims
WHERE target.tableoid = victims.tableoid
  AND target.ctid = victims.ctid
